export const recoverySeedsV33 = [{"id": "mcs-v33-recovered-carnival", "name": "Carnaval", "sourceName": "CARNAVAL INGLÊS - TUDO SALA DE AULA.pdf", "pages": ["<p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:center;font-size:13pt;\"><strong>CARNIVAL</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\"><strong>Read and answer questions 1 – 6.</strong></p><p style=\"text-align:center\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:65%;max-width:100%;height:auto\"></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:justify;\">Carnival is a traditional party that takes place in different parts of the world, being the most celebrated in Brazil. The word Carnival comes from the Latin, “carnis levale”, which means “to remove the meat”. Carnival is a festival traditionally linked to Catholicism, as its celebration precedes “Lent”. Carnival is not a Brazilian invention, as its origin dates back to antiquity.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:justify;\">In Brazil, carnival began in the colonial period. One of the first carnival manifestations was the “entrudo”, a game of Portuguese origin played by slaves. Carnival usually involves a public feast, with a parade combining some circus elements and masks.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:right;font-style:italic;\">Texto: Tudo Sala de Aula / 2023</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>1. The text is intended</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">a) to teach.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">b) to criticize.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">c) to explain.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">d) to inform.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>2. About the text, mark the TRUE option.</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">a) Carnival happens everywhere in the world.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">b) Brazil is the country that least celebrates Carnival.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">c) Carnival is not a traditional and popular feast.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">d) Many Brazilians hold a carnival party.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>3. In Brazil, when did carnival begin?</strong></p><div class=\"ped-answer-lines\"><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span></div><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>4. Segundo o texto, o carnaval significa</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">a) retirar a carne.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">b) limpar a carne.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">c) purificar a carne.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">d) lavar a mente.</p>", "<p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>5. Read the statements below and mark (F) for FALSE and (T) for TRUE.</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">a. (   ) Carnival is a Brazilian invention.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">b. (   ) Catholicism is related to Carnival.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">c. (   ) Carnival is a traditional Brazilian celebration.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">d. (   ) The origin of carnival is very old.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">e. (   ) Carnival happens only in closed places.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>6. Write about Brazilian carnival according to the text.</strong></p><div class=\"ped-answer-lines\"><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span></div><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>7. Match the carnival figures to their names.</strong></p><table style=\"width:100%;border-collapse:collapse\"><tbody><tr><td style=\"width:48%;height:16mm;border:none\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:55px;max-width:100%;height:auto\">　○</td><td style=\"border:none\">○　King Momo</td></tr><tr><td style=\"width:48%;height:16mm;border:none\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:55px;max-width:100%;height:auto\">　○</td><td style=\"border:none\">○　Giant puppets</td></tr><tr><td style=\"width:48%;height:16mm;border:none\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:55px;max-width:100%;height:auto\">　○</td><td style=\"border:none\">○　Serpentine</td></tr><tr><td style=\"width:48%;height:16mm;border:none\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:55px;max-width:100%;height:auto\">　○</td><td style=\"border:none\">○　Mask</td></tr><tr><td style=\"width:48%;height:16mm;border:none\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:55px;max-width:100%;height:auto\">　○</td><td style=\"border:none\">○　Samba dancer</td></tr><tr><td style=\"width:48%;height:16mm;border:none\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:55px;max-width:100%;height:auto\">　○</td><td style=\"border:none\">○　Tambourine</td></tr><tr><td style=\"width:48%;height:16mm;border:none\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:55px;max-width:100%;height:auto\">　○</td><td style=\"border:none\">○　Fantasy</td></tr></tbody></table>", "<p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\"><strong>Read and answer questions 8 – 10.</strong></p><p style=\"text-align:center\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:58%;max-width:100%;height:auto\"></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>8. According to Armandinho, what does carnival mean?</strong></p><div class=\"ped-answer-lines\"><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span></div><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>9. According to Armandinho, his friend shouldn&#x27;t</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">a) like carnival.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">b) wear a mask.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">c) eat during carnival.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-bottom:0;\">d) talk about carnival.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;margin-top:5pt;\"><strong>10. For Armandinho, why should not the girl participate in the carnival?</strong></p><div class=\"ped-answer-lines\"><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span></div>"]}, {"id": "mcs-v33-recovered-uk-culture", "name": "UK English Culture", "sourceName": "Atividade 1 - UK English Culture.pdf", "pages": ["<p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:center;font-size:13pt;\"><strong>ENGLISH CULTURE / WE3</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">(GO-EF05LI07) Identificar informações explícitas e implícitas em textos, colaborativamente e/ou individualmente, antecipando o sentido global por inferências, com base em conhecimento prévio e entendimento do texto, para aprimorar a compreensão de textos em língua inglesa.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">(GO-EF05LI08) Ler e interpretar textos diversos para desenvolver criticidade e autonomia leitora, estabelecendo relações com sua realidade.</p><p style=\"text-align:center\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:22%;max-width:100%;height:auto\"></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:justify;\">Conhecer a Cultura de um país e de seu povo possibilita conhecermos mais acerca do mundo que vivemos. Cada país, cidade, região ou estado possui seus hábitos, costumes, sotaques, alimentação, vestimentas, lugares turísticos, comportamento, língua, expressão artística e cultural própria e que fazem parte de sua cultura. O respeito e a valorização dessa diversidade nos tornam cidadãos conscientes e amplia nosso conhecimento de mundo e repertório cultural. Leia o texto abaixo e responda as questões.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\"><strong>QUESTÃO 1 – Read the text below about English Culture and answer the questions in your notebook. (Leia o texto abaixo sobre a Cultura Inglesa e responda as perguntas em seu caderno.)</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:center;font-size:13pt;\"><strong>English Culture</strong></p><p style=\"text-align:center\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:24%;max-width:100%;height:auto\"></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:justify;\">England is famous for its long and old history, it has more than 900 years old. England is famous for its Royal Family, with king, queens, princes and princesses, its Castles and Historic houses. Buckingham Palace is their official residence. Windsor Castle is the oldest royal residence still in use. It is famous for its educational institutes, like Eton College and Summerhill School. It has some of the most famous universities of the world like Oxford, Cambridge, Brighton, Sussex and London universities.</p>", "<p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:justify;\">Some of the world’s greatest pop stars – the Beatles, David Bowie, Queen, Phil Collins, the Rolling Stones, Oasis and the Spice Girls are from England. It has one of the most world famous watch: Big Ben. People usually drink tea every afternoon. A famous writer is William Shakespeare, he wrote: Hamlet, Othello, and Romeo and Juliet.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:justify;\">It has green hills and fertile lowlands. England is famous for its double decker bus, telephone boxes (cabines), Queen’s guards which wear a black hat made of bear’s skin. It is famous for its creams and butters and for its delicious cheeses: Stilton, Cheshire, Cheddar and others. It has lots of pubs, people usually go there to watch a football game, play pool or just to have a beer.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">Vocabulary – bear&#x27;s skin: pele de urso / beer: cerveja / black hat: chapéu preto / castle: castelo / creams and butters: cremes e manteigas / decker bus: ônibus de dois andares / double: dobro / England: Inglaterra / fertile lowlands: planícies férteis / greatest: o melhor / green hills: colinas verdes / like: como / most: maioria / people: pessoas / pool: sinuca / pubs: bares / still: ainda / tea: chá / watch: relógio / wear: vestir / world’s: do mundo / writer: escritor / wrote: escrito.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">a) What caught your attention in English Culture? (O que chamou sua atenção na Cultura Inglesa?)</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">b) How old is England? (Quantos anos têm a Inglaterra?)</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">c) Who makes up the Royal Family? (Quem compõe a Família Real?)</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">d) What are the official residences of the Royal Family? (Quais são as residências oficiais da Família Real?)</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">e) What are the most famous universities in England? (Quais são as universidades mais famosas da Inglaterra?)</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">f) Do you know some names of the world’s greatest pop stars from England? (Você conhece alguns nomes das maiores estrelas pop do mundo da Inglaterra?)</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">g) Who was William Shakespeare? (Quem foi William Shakespeare?)</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">h) What do people usually do in pubs? (O que as pessoas costumam fazer nos pubs?)</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">i) Name at least 3 historical monuments according to the last paragraph. (Cite pelo menos 3 monumentos históricos de acordo com o último parágrafo.)</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">j) Now, talk about what people generally like to do there, building on the last paragraph as well. (Agora, fale sobre o que as pessoas geralmente gostam de fazer lá, com base também no último parágrafo.)</p>", "<p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\"><strong>QUESTÃO 2 – Can you identify the words that tell us about culture? Circle them: (Você pode identificar as palavras que nos falam sobre cultura? Copie-as.)</strong></p><p style=\"text-align:center\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:56%;max-width:100%;height:auto\"></p><div class=\"ped-answer-lines\"><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span><span class=\"ped-answer-line\" style=\"display:block;height:6mm;min-height:6mm;border-bottom:1px solid #333\">&nbsp;</span></div><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\"><strong>QUESTÃO 3 – Connect the picture to the correct vocabulary about culture: (Ligue a figura até o vocabulário correto acerca da cultura.)</strong></p><p style=\"text-align:center\"><img src=\"data:image/jpeg;base64,\" alt=\"Imagem original\" style=\"width:58%;max-width:100%;height:auto\"></p>", "<p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\"><strong>QUESTÃO 4</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">Draw or cut and glue pictures that represent your culture: (Desenhe ou recorte e cole figuras que representam sua cultura; pode só escrever também).</p><div style=\"border:1px solid #333;border-radius:12px;min-height:36mm;text-align:center;margin:4pt 0;padding:4pt\"><strong>FOOD AND DRINK</strong><p><br></p></div><div style=\"border:1px solid #333;border-radius:12px;min-height:36mm;text-align:center;margin:4pt 0;padding:4pt\"><strong>COSTUMES</strong><p><br></p></div><div style=\"border:1px solid #333;border-radius:12px;min-height:36mm;text-align:center;margin:4pt 0;padding:4pt\"><strong>CELEBRATIONS</strong><p><br></p></div><div style=\"border:1px solid #333;border-radius:12px;min-height:36mm;text-align:center;margin:4pt 0;padding:4pt\"><strong>SIGHTSEEING</strong><p><br></p></div><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\"><strong>DID YOU KNOW? (Leia: Você sabia?)</strong></p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;\">O Reino Unido é uma união política estabelecida entre alguns países. Essa união constitui uma só nação, que é tratada como um único país soberano. Os 4 países que formam o Reino Unido são: Inglaterra, País de Gales, Irlanda do Norte e Escócia. Reforçando que a República da Irlanda não faz parte do Reino Unido, somente a Irlanda do Norte. Pesquise mais sobre isso quando puder.</p><p style=\"font-family:Arial,sans-serif;font-size:11pt;line-height:1.15;margin:0 0 4pt;text-align:right;font-style:italic;\">English Week / EW3 / Mr. Marks</p>"]}];
